4. //! Bounded LRU cache backed by `BTreeMap`.
5. //!
6. //! Entries are stored in a `BTreeMap` keyed by a caller-chosen type `K` that
7. //! implements `Ord + Clone`. A monotonic counter tracks access order; on
8. //! eviction the entry with the smallest (oldest) counter value is removed.
9. //! Lookups bump the counter to mark the entry as recently used.
10. //!
11. //! # Capacity
12. //!
13. //! The cache is bounded by a capacity given at construction time. When the
14. //! cache is full, the least-recently-used entry is evicted before inserting a
15. //! new one.
16. //!
17. //! # Example
18. //!
19. //! ```
20. //! use cache::Cache;
21. //!
22. //! let mut cache: Cache<&str, i32> = Cache::new(2);
23. //! cache.put("a", 1);
24. //! cache.put("b", 2);
25. //! assert_eq!(*cache.get(&"a").unwrap(), 1);
26. //!
27. //! // Inserting a third entry evicts "b" (least recently used).
28. //! cache.put("c", 3);
29. //! assert!(cache.get(&"b").is_none());
30. //! assert_eq!(*cache.get(&"c").unwrap(), 3);
31. //! ```
32. 
33. #![cfg_attr(not(feature = "std"), no_std)]
34. #![cfg_attr(verus_keep_ghost, feature(proc_macro_hygiene))]
35. 
36. //==================================================================================================
37. // Imports
38. //==================================================================================================
39. 
40. extern crate alloc;
41. 
42. use ::alloc::collections::BTreeMap;
43. use ::core::ops::{
44.     Deref,
45.     DerefMut,
46. };
47. 
48. use vstd::prelude::*;
49. #[cfg(verus_keep_ghost)]
50. include!("lib.spec.rs");
51. #[cfg(verus_keep_ghost)]
52. include!("lib.proof.rs");
53. 
54. 
55. //==================================================================================================
56. // Cache Entry
57. //==================================================================================================
58. 
59. /// A single entry in the cache.
60. #[derive(Clone)]
61. struct CacheEntry<V> {
62.     /// Cached value.
63.     value: V,
64.     /// Last-access counter (higher = more recently used).
65.     last_used: u64,
66. }
67. 
68. //==================================================================================================
69. // Cache Guard
70. //==================================================================================================
71. 
72. ///
73. /// # Description
74. ///
75. /// RAII guard providing a reference to a cached entry.
76. ///
77. /// Created by [`Cache::get()`]. Dereferences to `&V` for read access
78. /// and `&mut V` for write access. The LRU counter is bumped when the guard
79. /// is created.
80. ///
81. pub struct CacheGuard<'a, V> {
82.     /// Mutable reference to the cached value.
83.     value: &'a mut V,
84. }
85. 
86. impl<V> Deref for CacheGuard<'_, V> {
87.     type Target = V;
88. 
89.     fn deref(&self) -> &V {
90.         self.value
91.     }
92. }
93. 
94. impl<V> DerefMut for CacheGuard<'_, V> {
95.     fn deref_mut(&mut self) -> &mut V {
96.         self.value
97.     }
98. }
99. 
100. //==================================================================================================
101. // Cache
102. //==================================================================================================
103. 
104. ///
105. /// # Description
106. ///
107. /// A bounded cache using access-counter LRU approximation.
108. ///
109. /// Entries are stored in a `BTreeMap` keyed by `K`. A monotonic counter tracks access order;
110. /// on eviction the entry with the smallest (oldest) counter value is removed. Lookups bump the
111. /// counter to mark the entry as recently used.
112. ///
113. pub struct Cache<K, V> {
114.     /// Cached entries.
115.     entries: BTreeMap<K, CacheEntry<V>>,
116.     /// Monotonically increasing counter for LRU ordering.
117.     counter: u64,
118.     /// Maximum number of entries.
119.     capacity: usize,
120. }
121. 
122. impl<K: Ord + Clone, V> Cache<K, V> {
123.     ///
124.     /// # Description
125.     ///
126.     /// Creates a new empty cache with the given capacity.
127.     ///
128.     /// # Parameters
129.     ///
130.     /// - `capacity`: Maximum number of entries the cache can hold.
131.     ///
132.     pub const fn new(capacity: usize) -> Self {
133.         Self {
134.             entries: BTreeMap::new(),
135.             counter: 0,
136.             capacity,
137.         }
138.     }
139. 
140.     ///
141.     /// # Description
142.     ///
143.     /// Looks up a cached value and bumps its LRU counter on hit.
144.     ///
145.     /// # Parameters
146.     ///
147.     /// - `key`: The cache key to look up.
148.     ///
149.     /// # Returns
150.     ///
151.     /// An RAII guard providing access to the cached value, or `None` on cache miss.
152.     ///
153.     pub fn get(&mut self, key: &K) -> Option<CacheGuard<'_, V>> {
154.         if let Some(entry) = self.entries.get_mut(key) {
155.             self.counter += 1;
156.             entry.last_used = self.counter;
157.             Some(CacheGuard {
158.                 value: &mut entry.value,
159.             })
160.         } else {
161.             None
162.         }
163.     }
164. 
165.     ///
166.     /// # Description
167.     ///
168.     /// Inserts a value, evicting the least-recently-used entry if at capacity.
169.     ///
170.     /// # Parameters
171.     ///
172.     /// - `key`: The cache key to insert or update.
173.     /// - `value`: The value to store.
174.     ///
175.     pub fn put(&mut self, key: K, value: V) {
176.         // A zero-capacity cache cannot store entries.
177.         if self.capacity == 0 {
178.             return;
179.         }
180. 
181.         // If the key is already present, update in place.
182.         if let Some(entry) = self.entries.get_mut(&key) {
183.             self.counter += 1;
184.             entry.value = value;
185.             entry.last_used = self.counter;
186.             return;
187.         }
188. 
189.         // Evict the LRU entry if at capacity.
190.         if self.entries.len() >= self.capacity {
191.             self.evict();
192.         }
193. 
194.         self.counter += 1;
195.         self.entries.insert(
196.             key,
197.             CacheEntry {
198.                 value,
199.                 last_used: self.counter,
200.             },
201.         );
202.     }
